struct Builder {std::vector<char> b;unsigned alloc(size_t n){size_t o=(b.size()+7)&~size_t(7);if(o+n>UINT32_MAX)throw std::runtime_error("GPU raw addressing capacity");b.resize(o+n);return unsigned(o);}template<class T>void put(unsigned o,const T& x){memcpy(b.data()+o,&x,sizeof x);}template<class T>unsigned array(const std::vector<T>&v){auto o=alloc(std::max(size_t(8),v.size()*sizeof(T)));if(!v.empty())memcpy(b.data()+o,v.data(),v.size()*sizeof(T));return o;}};
